import{b as s,O as n,g as a,j as e}from"./chunks/framework.DSt9LnBW.js";const c=JSON.parse('{"title":"大模型压测的特殊之处","description":"","frontmatter":{},"headers":[],"relativePath":"performance/locust/llm/basics/index.md","filePath":"性能测试/2.Locust/6.大模型压测/27.大模型压测的特殊之处.md","lastUpdated":1789914310000}'),i={name:"performance/locust/llm/basics/index.md"};function o(p,t,r,d,l,h){return n(),a("div",null,[...t[0]||(t[0]=[e(`<h1 id="大模型压测的特殊之处" tabindex="-1">大模型压测的特殊之处 <a class="header-anchor" href="#大模型压测的特殊之处" aria-label="Permalink to &quot;大模型压测的特殊之处&quot;">​</a></h1><blockquote><p>前面五篇练的都是「一个请求 = 发出去 + 等完整响应回来」这套。大模型接口把其中三条假设全打破了：<strong>用户等的不是响应，是第一个字</strong>；<strong>响应不是一个包，是一串 token</strong>；<strong>计费不按请求数，按 token</strong>。照搬前面那套压法，报告会给你一堆看起来正常、实际毫无意义的数字。</p></blockquote><h2 id="一次请求的时间去哪儿了" tabindex="-1">一次请求的时间去哪儿了 <a class="header-anchor" href="#一次请求的时间去哪儿了" aria-label="Permalink to &quot;一次请求的时间去哪儿了&quot;">​</a></h2><p>先看一次最普通的流式对话请求——testing-online 的 Mock 接口 <code>/api/llm/v1/chat/completions</code>，默认参数（首 token 延迟 20ms、每个 token 间隔 2ms、输出 64 个 token）：</p><p><img src="https://op.yychuiyan.com/docs-blog/ttft-e2e-timeline.png" alt="一次流式 LLM 请求的时间分解：从发出请求到首个 token 是 TTFT（约 22ms），到 finish_reason 结束是 E2E（约 150ms），中间是 64 个 token 的流式传输"></p><p>按默认参数推算（首 token 延迟 20ms + 每个 token 2ms × 64 个）：</p><table tabindex="0"><thead><tr><th>指标</th><th>推算值</th><th>占比</th></tr></thead><tbody><tr><td><strong>TTFT</strong>（首 token 时间）</td><td>≈ 22 ms</td><td>15%</td></tr><tr><td><strong>流式传输</strong>（剩下的 token）</td><td>≈ 128 ms</td><td>85%</td></tr><tr><td><strong>E2E</strong>（端到端总时长）</td><td>≈ 150 ms</td><td>100%</td></tr><tr><td><strong>TPOT</strong>（每个输出 token 的间隔）</td><td>≈ 2 ms</td><td>—</td></tr></tbody></table><blockquote><p>这组数是按接口默认参数<strong>推算</strong>的，用来理解结构；真实数值请自己压一遍。TTFT 比理论值多 2ms，是因为首个携带 <code>role</code> 的 chunk 之后，第一个<strong>含内容</strong>的 chunk 还要等一个 <code>token_interval_ms</code>——&quot;首字节&quot;和&quot;首个字&quot;在这里不是一回事，第 29 章<a href="/performance/locust/llm/ttft/">流式输出与 TTFT</a> 会展开。</p><p>✅ <strong>这条因果链已在第 29 章实测证实</strong>：把 <code>token_interval_ms</code> 调到 200 后，实测 <code>role</code> chunk 在 36.1ms、首个内容 chunk 在 237.2ms，<strong>正好差开 201ms</strong>——多出来的就是一个完整的 token 间隔。</p></blockquote><p>关键在比例：<strong>用户感知的 15%，和报告里那个 150ms，是两个东西</strong>。</p><p>如果按前五篇的习惯只看「平均响应时间」，你会得到一个 150ms 的漂亮数字，然后<strong>完全不知道其中 22ms 是&quot;模型在想&quot;、128ms 是&quot;在往外吐&quot;</strong>。而这两段的优化手段完全不同：前者要动推理/排队，后者要动带宽和 token 生成速度。</p><h2 id="五个指标-各有各的陷阱" tabindex="-1">五个指标，各有各的陷阱 <a class="header-anchor" href="#五个指标-各有各的陷阱" aria-label="Permalink to &quot;五个指标，各有各的陷阱&quot;">​</a></h2><p>这是 testing-online 大模型控制台里列的口径表，直接拿来看：</p><table tabindex="0"><thead><tr><th>指标</th><th>全称</th><th>怎么算</th><th>容易错的地方</th></tr></thead><tbody><tr><td><strong>TTFT</strong></td><td>Time To First Token</td><td>从发出请求到收到第一个<strong>含内容</strong>的 chunk，只能在客户端从流里量</td><td>思考模式下首个 token 是思考内容，与内容首 token 不是一回事</td></tr><tr><td><strong>TPOT / ITL</strong></td><td>Time Per Output Token / Inter-Token Latency</td><td>（E2E − TTFT）÷（输出 token 数 − 1）</td><td>token 数要用 <code>usage.completion_tokens</code>，<strong>不能数 chunk 个数</strong></td></tr><tr><td><strong>E2E</strong></td><td>端到端总时长</td><td>从发出请求到收到最后一个 chunk</td><td>与 TTFT 是两个指标，混在一起看会掩盖首包慢的问题</td></tr><tr><td><strong>Tokens/s</strong></td><td>token 吞吐</td><td>输出 token 总数 ÷ 总时长</td><td>prompt 缓存命中会显著抬高这个值，测出来会虚好</td></tr><tr><td><strong>RPS</strong></td><td>请求吞吐</td><td>完成请求数 ÷ 总时长</td><td>prompt 长度差异大时，RPS 不能横向比较</td></tr></tbody></table><p>三条最容易踩的：</p><p>1）<strong>TTFT 必须流式才量得到</strong>。非流式请求服务端是「想完了再一次性返回」，客户端手上只有一个总时长，<code>TTFT</code> 这个数<strong>根本不存在</strong>。别在非流式报告里找它。</p><p>2）<strong>TPOT 的分母是 token 数，不是 chunk 数</strong>。流式响应里除了内容 chunk，还有 <code>role</code> chunk、<code>finish_reason</code> chunk、<code>usage</code> chunk——数 chunk 会把分母算大，TPOT 算小。</p><p>3）<strong>RPS 在 LLM 场景几乎不能横向比</strong>。同样 100 RPS，一问一答（10 token）和长文生成（2000 token）的负载差两个数量级。<strong>容量结论要用 tokens/s 表述，不是 RPS</strong>——第 31 章<a href="/performance/locust/llm/capacity/">容量结论与成本</a>细讲。</p><h2 id="坑一-http-200-也可能是失败" tabindex="-1">坑一：HTTP 200 也可能是失败 <a class="header-anchor" href="#坑一-http-200-也可能是失败" aria-label="Permalink to &quot;坑一：HTTP 200 也可能是失败&quot;">​</a></h2><p>普通接口的错误很诚实：4xx / 5xx 一眼可见。大模型接口有一种<strong>假成功</strong>——</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP 200</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>{&quot;choices&quot;:[{&quot;message&quot;:{&quot;content&quot;:&quot;&quot;},&quot;finish_reason&quot;:&quot;stop&quot;}],&quot;usage&quot;:{&quot;completion_tokens&quot;:0}}</span></span></code></pre></div><p>状态码 200、结构完整、<code>finish_reason</code> 还是正常的 <code>stop</code>，但<strong>一个 token 都没输出</strong>。testing-online 专门留了 <code>?error=empty</code> 来注入这个场景。</p><p>为什么这在真实环境里常见：上游限流后降级、模型内部异常提前收尾、流被中间层截断。对客户端来说，<strong>只看状态码的错误率统计会把这类请求全部记成成功</strong>。</p><p>所以大模型压测的断言必须多看一层：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ❌ 只看状态码：假成功会被记成成功</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resp.status_code </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp.failure(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HTTP </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp.status_code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ✅ 状态码 + 内容：两个都要判</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> resp.status_code </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp.failure(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HTTP </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">resp.status_code</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">elif</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> content:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp.failure(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HTTP 200 但一个 token 都没输出（假成功）&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    resp.success()</span></span></code></pre></div><blockquote><p>这类问题的通用处理方式，第 9 章<a href="/performance/locust/core/response-validation/">响应校验与断言</a>讲过原则；大模型这边只是把&quot;内容非空&quot;从可选项变成了必选项。</p></blockquote><h2 id="坑二-平均值会藏住长尾" tabindex="-1">坑二：平均值会藏住长尾 <a class="header-anchor" href="#坑二-平均值会藏住长尾" aria-label="Permalink to &quot;坑二：平均值会藏住长尾&quot;">​</a></h2><p>真实 LLM 的首 token 延迟不是稳定值，而是<strong>一个基线 + 一段抖动 + 偶发的长尾尖峰</strong>。testing-online 的 Mock 把这个特性做成了可注入参数：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ttft_ms=20            # 基线：20ms</span></span>
<span class="line"><span>ttft_jitter_ms=50     # 均匀抖动：0~50ms 随机叠加</span></span>
<span class="line"><span>ttft_spike_rate=5     # 5% 的请求会命中尖峰</span></span>
<span class="line"><span>ttft_spike_ms=500     # 尖峰额外加 500ms</span></span></code></pre></div><p>配置成这样之后，多数请求的首 token 在 20~70ms，但<strong>每 20 个请求里有 1 个要等 570ms</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P50  ≈ 45ms     ← 看着很健康</span></span>
<span class="line"><span>P95  ≈ 570ms    ← 才是用户偶尔会骂人的那一下</span></span>
<span class="line"><span>平均 ≈ 70ms     ← 被 5% 的尖峰拉高，但离 P95 还差得远</span></span></code></pre></div><p><strong>平均值在这里是最没用的那个数</strong>：它比 P50 大、比 P95 小，谁都不代表。用户抱怨的从来不是&quot;平均 70ms 有点慢&quot;，而是&quot;每划几下就卡一次&quot;。</p><p>只有抖动没有尖峰时，P50 到 P99 会平得像一条线——<strong>那才是不正常的</strong>，通常说明压测打得太轻、没触发排队。</p><p>所以大模型压测的报告要看 <strong>P95 / P99</strong>，配合分布图，而不是平均值。第 25 章<a href="/performance/locust/practice/report-reading/">报告解读</a>讲过怎么从 <code>_stats_history.csv</code> 里看出这些。</p><h2 id="坑三-压的是「谁」要分清楚" tabindex="-1">坑三：压的是「谁」要分清楚 <a class="header-anchor" href="#坑三-压的是「谁」要分清楚" aria-label="Permalink to &quot;坑三：压的是「谁」要分清楚&quot;">​</a></h2><p>大模型压测有个前面所有篇章都没有的问题：<strong>你的压测机可能先撑不住</strong>。</p><p>原因很直接——LLM 的响应体比你前面压的所有接口都大：</p><table tabindex="0"><thead><tr><th>接口</th><th>单次响应体</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /api/products/:id</code></td><td>~0.3 KB</td><td>一个商品</td></tr><tr><td><code>GET /api/scenario/payload?size=100</code></td><td>~100 KB</td><td>专门造的带宽场景</td></tr><tr><td><strong>一次 2000 token 的对话</strong></td><td><strong>~380 KB</strong></td><td>而且<strong>持续 4 秒</strong></td></tr></tbody></table><p>最后一行按 Mock 的实现估：<strong>一个 token 一个 chunk</strong>，每个 chunk 的 JSON（含 <code>id</code> / <code>object</code> / <code>model</code> 等字段）约 190 字节，2000 个就是 ~380 KB。真实模型可能把多个 token 塞进一个 chunk，体积会小些，但<strong>量级依然远大于普通接口</strong>。</p><p>真正的问题是<strong>连接会长时间挂着</strong>：一个 4 秒的流式请求，客户端要占用一个连接慢慢读。并发一上去，压测机的文件描述符（第 2 章<a href="/performance/locust/intro/setup/">安装与环境准备</a>讲过 <code>ulimit -n</code>）、CPU（解析 SSE 是实打实的开销）都会成为瓶颈。</p><p>判断方法还是第 16 章<a href="/performance/locust/scenarios/client-performance/">单机压不上去怎么办</a>那套：<strong>压测机的 CPU 是否打满</strong>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 压测进行中，另开一个终端看 Locust 进程吃了多少 CPU</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">top</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgrep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> locust</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>如果压测机 CPU 先到 90%，那报告的 RPS 反映的是<strong>你的笔记本</strong>，不是模型服务。这时候要换 <code>FastHttpUser</code>、上多进程或分布式——但注意：<strong>流式场景下 <code>FastHttpUser</code> 的收益和普通接口不同</strong>，具体见第 30 章<a href="/performance/locust/llm/openai-user/">OpenAIUser 与自定义客户端</a>。</p><h2 id="testing-online-提供了什么" tabindex="-1">testing-online 提供了什么 <a class="header-anchor" href="#testing-online-提供了什么" aria-label="Permalink to &quot;testing-online 提供了什么&quot;">​</a></h2><p>本项目的 Mock 是<strong>刻意做成尖的</strong>：它不对应任何真实算力，但要把大模型接口的三个特性都演出来。</p><table tabindex="0"><thead><tr><th>特性</th><th>靠什么演</th><th>在哪一章</th></tr></thead><tbody><tr><td>TTFT 远大于普通接口</td><td><code>ttft_ms</code> / <code>ttft_jitter_ms</code> / <code>ttft_spike_rate</code></td><td>第 29 章</td></tr><tr><td>流式、逐 token</td><td><code>stream</code> + <code>token_interval_ms</code></td><td>第 29 章</td></tr><tr><td>按 token 计费</td><td>响应带 <code>usage</code></td><td>第 31 章</td></tr><tr><td>限流与退避</td><td><code>?error=429</code> + <code>Retry-After</code></td><td>第 28 章</td></tr><tr><td>假成功</td><td><code>?error=empty</code></td><td>第 28 章</td></tr><tr><td>截断</td><td><code>answer_tokens &gt; max_tokens</code></td><td>第 28 章</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 先手工打一发，感受一下流式输出</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:3001/api/llm/v1/chat/completions&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;model&quot;:&quot;mock-gpt&quot;,&quot;messages&quot;:[{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;你好&quot;}],&quot;stream&quot;:true}&#39;</span></span></code></pre></div><p><code>-N</code> 是关掉 curl 的输出缓冲，不然你会看到它卡一会儿然后一次性吐完——<strong>这不是接口的问题，是你没关缓冲</strong>。排查流式问题时先确认工具本身没有在缓冲。</p><blockquote><p>⚠️ <strong>Mock ≠ 容量</strong>。<code>/api/llm/v1</code> 只模拟<strong>接口契约与行为特征</strong>，它的响应时间是 <code>setTimeout</code> 排出来的，不是算出来的。<strong>用它练脚本、练断言、练报告解读；要容量结论必须换真实上游</strong>（第 31 章会给出一条对照路径）。</p></blockquote><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>用户等的是第一个字</strong>：TTFT 通常只占 E2E 的一小部分，但它才是体感；只看平均响应时间会完全错过</li><li><strong>五个指标五个坑</strong>：TTFT 必须流式才量得到；TPOT 分母是 token 数不是 chunk 数；RPS 在 LLM 场景不能横向比</li><li><strong>⚠️ HTTP 200 ≠ 成功</strong>：<code>completion_tokens = 0</code> 的假成功要被单独判为失败，只看状态码会漏</li><li><strong>⚠️ 平均值最没用</strong>：TTFT 的长尾才是用户抱怨的来源，要看 P95 / P99</li><li><strong>先确认压测机没先撑住</strong>：流式请求长时间占用连接，压测机 CPU / 句柄都可能先到顶</li><li><strong>容量结论用 tokens/s 表述</strong>，不用 RPS</li><li><strong>Mock 用来练手，不用来得结论</strong></li></ul><p>下一章先把接口的&quot;脾气&quot;摸清楚：哪些参数放哪里才生效、六种注入分别长什么样、以及<strong>参数放错位置会被静默忽略</strong>这个最难查的坑。</p>`,51)])])}const g=s(i,[["render",o]]);export{c as __pageData,g as default};
